const P=()=>S.p; const segById=id=>S.segs.find(s=>s.id===id); const segAt=tm=>S.segs.find((s,i)=>tm>=s.start&&(tm<s.end||(i===S.segs.length-1&&tm<=s.end)))||null;
const busy=()=>{ const x=S.p?.status; return !!S.p&&(x==='PROCESSING'||x==='QUEUED'||x==='Đang xử lý'||x==='Đang chờ xử lý'||x==='Đang OCR phụ đề'); };
const saveSettings=o=>api.updateSettings(S.p.id,o).catch(()=>toast(t('Lưu cài đặt thất bại','Failed to save settings'),'error'));
let ocrEventSource=null, ocrEventProject=null, ocrLastEventError=0, ocrColorSaveTimer=null, ocrSseConnected=false;
function closeOcrEvents(){ if(ocrEventSource){ try{ocrEventSource.close();}catch(e){} } ocrEventSource=null; ocrEventProject=null; ocrSseConnected=false; }
function pushOcrLog(message,percent=null,kind='log'){ const line={message:String(message||''),percent:Number.isFinite(Number(percent))?Number(percent):null,kind,ts:Date.now()}; S.ocrLogs.push(line); if(S.ocrLogs.length>24) S.ocrLogs=S.ocrLogs.slice(-24); renderOcrLiveLog(); }
function renderOcrLiveLog(){ const box=$('#ocrLiveLog'), lines=$('#ocrLiveLines'), state=$('#ocrLiveState'); if(!box||!lines||!state) return; const isOcr=S.p?.subtitleSource==='ocr'; box.hidden=!isOcr; state.textContent=S.busyJob==='transcribe'&&busy()?t('RUNNING','RUNNING'):S.ocrLogs.length?t('READY','READY'):t('IDLE','IDLE'); lines.innerHTML=''; S.ocrLogs.slice(-3).forEach(x=>{ const el=h('div',{class:'ocr-live-line'},h('span',null,x.kind==='segment'?'▸ ':''),h('span',null,x.message),x.percent!=null?h('span',{class:'pct'},` · ${Math.round(x.percent)}%`):null); if(x.kind==='segment') el.classList.add('seg'); lines.append(el); }); }
function connectOcrEvents(){ if(!S.p||api!==httpApiInstance||!CFG.apiBase||S.p.subtitleSource!=='ocr') return; const id=String(S.p.id); if(ocrEventProject===id&&ocrEventSource) return; closeOcrEvents(); const url=CFG.apiBase.replace(/\/$/,'')+'/api/projects/'+encodeURIComponent(id)+'/ocr/events'; try{ ocrEventSource=new EventSource(url); ocrEventProject=id; ocrEventSource.onopen=()=>{ ocrSseConnected=true; if(S.busyJob==='transcribe'&&S.p?.subtitleSource==='ocr'&&pollTimer){ clearInterval(pollTimer); pollTimer=null; } pushOcrLog(t('Kênh OCR realtime đã kết nối','OCR realtime channel connected'),null,'log'); renderOcrLiveLog(); }; ocrEventSource.onmessage=e=>{ let ev=null; try{ev=JSON.parse(e.data||'{}')}catch(err){return;} handleOcrEvent(ev); }; ocrEventSource.onerror=()=>{ ocrSseConnected=false; const now=Date.now(); if(now-ocrLastEventError>5000){ ocrLastEventError=now; pushOcrLog(t('Kênh realtime tạm gián đoạn — dùng polling dự phòng trong lúc trình duyệt tự kết nối lại.','Realtime channel interrupted — fallback polling is enabled while the browser reconnects.'),null,'log'); startPolling(); } }; }catch(e){ ocrSseConnected=false; pushOcrLog(e.message||'SSE unavailable',null,'log'); startPolling(); } }
function handleOcrEvent(ev){ if(!ev) return; const type=String(ev.type||'progress'); if(type==='progress'){ const pct=Number(ev.overall_percent); if(S.p){S.p.progress=Number.isFinite(pct)?pct:S.p.progress; S.p.stage='OCR'; S.p.status='PROCESSING';} const msg=ev.message||(ev.phase==='ocr_backend'?t(`Backend ${ev.ocr_backend||'PP-OCRv5'} · ${ev.ocr_gpu_active?'GPU':'CPU'}${Array.isArray(ev.runtime_providers)&&ev.runtime_providers.includes('CUDAExecutionProvider')?' · CUDA':''} · lang=${ev.lang||'auto'}`,`Backend ${ev.ocr_backend||'PP-OCRv5'} · ${ev.ocr_gpu_active?'GPU':'CPU'}${Array.isArray(ev.runtime_providers)&&ev.runtime_providers.includes('CUDAExecutionProvider')?' · CUDA':''} · lang=${ev.lang||'auto'}`):`${ev.phase||'OCR'}${ev.phase_done!=null&&ev.phase_total?` ${ev.phase_done}/${ev.phase_total}`:''}`); pushOcrLog(msg,Number.isFinite(pct)?pct:null,'log'); renderOcrLiveLog(); renderTop(); renderStageInfo(); return; } if(type==='segment_preview'){ const raw=Object.assign({},ev.segment||{}); if(raw.start==null&&raw.start_time!=null) raw.start=Number(raw.start_time); if(raw.end==null&&raw.end_time!=null) raw.end=Number(raw.end_time); if(raw.start_sec==null&&raw.start_time!=null) raw.start_sec=Number(raw.start_time); if(raw.end_sec==null&&raw.end_time!=null) raw.end_sec=Number(raw.end_time); const tracking=raw.tracking_id!=null?String(raw.tracking_id):String(ev.segment_index||'preview'); raw.index=`preview:${tracking}`; raw.id=`preview:${tracking}`; raw.timing_source='streaming_preview'; raw.ocr_locked=false; raw.timing_locked=false; const mapped=mapSeg(raw,raw.translated_text||raw.translation||''); mapped.streamingPreview=true; mapped.ocrLocked=false; mapped.timingLocked=false; mapped.txStatus='pending'; const ix=S.segs.findIndex(x=>String(x.id)===String(mapped.id)); if(ix>=0) S.segs[ix]=Object.assign({},S.segs[ix],mapped); else S.segs.push(mapped); S.segs.sort((a,b)=>a.start-b.start); pushOcrLog(ev.message||t(`Đang hiện tạm câu ${tracking}`,`Streaming preview ${tracking}`),null,'segment'); renderSegList(); drawTimeline(); renderOcrLiveLog(); renderStageInfo(); return; } if(type==='segment'){ const raw=Object.assign({},ev.segment||{}); if(raw.start==null&&raw.start_time!=null) raw.start=Number(raw.start_time); if(raw.end==null&&raw.end_time!=null) raw.end=Number(raw.end_time); if(raw.start_sec==null&&raw.start_time!=null) raw.start_sec=Number(raw.start_time); if(raw.end_sec==null&&raw.end_time!=null) raw.end_sec=Number(raw.end_time); const mapped=mapSeg(raw,raw.translated_text||raw.translation||''); const ix=S.segs.findIndex(x=>String(x.id)===String(mapped.id)); if(ix>=0) S.segs[ix]=Object.assign({},S.segs[ix],mapped); else S.segs.push(mapped); S.segs.sort((a,b)=>a.start-b.start); pushOcrLog(ev.message||t(`Đã nhận segment ${mapped.id}`,`Received segment ${mapped.id}`),null,'segment'); renderSegList(); drawTimeline(); renderStageInfo(); return; } if(type==='complete'){ if(Array.isArray(ev.segments)) S.segs=ev.segments.map(x=>mapSeg(x,x.translated_text||x.translation||'')); if(S.p){S.p.status='TRANSCRIBED';S.p.stage=null;S.p.progress=100;S.p.ocrAudit=ev.audit||S.p.ocrAudit;S.busyJob=null;} pushOcrLog(ev.message||t('OCR hoàn tất — timeline đã khóa.','OCR complete — timeline locked.'),100,'segment'); renderSegList(); drawTimeline(); renderTop(); renderOcrLiveLog(); renderStageInfo(); closeOcrEvents(); return; } if(type==='cancelled'){if(S.p){S.p.status='CANCELLED';S.p.stage=null;S.busyJob=null;} pushOcrLog(ev.message||t('OCR đã hủy.','OCR cancelled.'));renderOcrLiveLog();return;} if(type==='error'){pushOcrLog(ev.message||t('OCR lỗi.','OCR error.'),null,'log');renderOcrLiveLog();} }
const saveStyle=()=>saveSettings({subtitle_style:styleOut(S.p.style,S.p.blur)});
