function normalizeTimelineForUi(list){
  // V20: UI is a read-only projection of the MASTER TIMELINE.
  // Never clamp, trim, sort, or otherwise alter source start/end here.
  return Array.isArray(list) ? list.map(x=>Object.assign({},x)) : [];
}
function selectSeg(id,{seek=true,scroll=false}={}){ S.sel=id; $$('.seg-card').forEach(c=>c.toggleAttribute('data-sel',c.dataset.id===id)); const s=segById(id); if(s&&seek) seekTo(S.p?.subtitleSource==='ocr'?subtitleSpan(s)[0]:s.start); if(scroll){ const c=$(`.seg-card[data-id="${id}"]`); c&&c.scrollIntoView({block:'nearest'}); } drawTimeline(); }
async function translateSeg(id){
  id=String(id); const s=segById(id); if(!s||s.txStatus==='running') return;
  s.txStatus='running'; renderSegList();
  try{ const r=await api.translateSegment(S.p.id,Number(id));
    Object.assign(s,{id:String(r.id??id),start:Number(r.start??s.start),end:Number(r.end??s.end),src:String(r.src??s.src),txt:String(r.txt??''),txStatus:'done',dubStatus:'none',dubError:null});
    toast(t('Đã dịch lại phân đoạn','Segment re-translated'),'success');
  }catch(e){ s.txStatus=s.txt?'done':'pending'; toast(e.message||t('Dịch lại thất bại','Re-translate failed'),'error'); }
  renderSegList(); drawTimeline(); updateSub();
}

async function dubSeg(id){ id=Number(id); const s=segById(String(id)); if(!s||s.txStatus!=='done'||s.dubStatus==='running') return; s.dubStatus='running'; renderSegList(); try{ const r=await api.dubSegment(S.p.id,id); if(r){ Object.assign(s,r); const st=Number(r.dub_start_sec??r.start_sec??s.speechStart??s.start??0); const du=Number(r.dub_duration??r.duration??0); s.dubStart=st; s.dubDuration=du; s.dub_end_sec=st+Math.max(0,du); s.dubStatus='done'; } else s.dubStatus='done'; s.dubError=null; }catch(e){ s.dubStatus='failed'; s.dubError=e.message; toast(e.message||t('Lồng tiếng thất bại','Dubbing failed'),'error'); } renderSegList(); drawTimeline(); }
function saveText(id,txt){ const s=segById(id); if(!s) return; const changed=txt!==s.txt; s.txt=txt; s.txStatus=txt?'done':'pending'; if(changed&&s.dubStatus==='done') s.dubStatus='none'; renderSegList(); drawTimeline(); updateSub(); if(changed) api.updateSegment(S.p.id,id,{translated_text:txt}).catch(()=>toast(t('Lưu bản dịch thất bại','Failed to save translation'),'error')); }
async function deleteSeg(id){ const ok=await confirmDlg({title:t('Xóa phân đoạn','Delete segment'),desc:t('Phân đoạn này (kèm bản dịch và lồng tiếng) sẽ bị xóa khỏi dự án và không thể khôi phục.','This segment, with its translation and dubbing, will be removed from the project and cannot be restored.'),confirmLabel:t('Xóa','Delete')}); if(!ok) return; try{await api.deleteSegment(S.p.id,id);S.segs=S.segs.filter(s=>s.id!==id);if(S.sel===id)S.sel=null;renderSegs();drawTimeline();}catch(e){toast(e.message||t('Xóa phân đoạn thất bại','Delete segment failed'),'error');} }
async function addSeg(after){ const prev=after?segById(after):null; const start=prev?prev.end:0; const next=S.segs.find(s=>s.start>=start+0.05); const end=Math.max(start+0.5,Math.min(start+3,next?next.start:start+3)); try{ const s=await api.addSegment(S.p.id,{start_sec:+start.toFixed(2),end_sec:+end.toFixed(2),source_text:''}); S.segs.push(s); S.segs.sort((a,b)=>a.start-b.start); renderSegs(); drawTimeline(); selectSeg(s.id,{scroll:true}); }catch(e){ toast(e.message,'error'); } }
function updateTiming(id,start,end){ const s=segById(id); if(!s) return; s.start=Number(start); s.end=Number(end); const payload={start_sec:s.start,end_sec:s.end}; if(S.p.subtitleSource==='ocr'||s.ocrLocked){ s.source_start=s.start; s.source_end=s.end; payload.source_start=s.start; payload.source_end=s.end; } renderSegList(); drawTimeline(); api.updateSegment(S.p.id,id,payload).catch(()=>toast(t('Lưu thời gian thất bại','Failed to save timing'),'error')); }
async function runJob(mode,body,label){ if(busy()) return; try{ const isOcr=mode==='transcribe' && String((body&&body.subtitle_source)||S.p?.subtitleSource||'').toLowerCase()==='ocr'; if(mode==='dub'){ const pv=providers(); body=Object.assign({provider:pv.tts||'xkira_tts',voice:pv.tts==='xkira_tts'?(pv.xkiraVoice||''): (pv.edgeVoice||'vi-VN-HoaiMyNeural'),rate:Number(pv.speed||1.3)},body||{}); } await api.startJob(S.p.id,mode,body); S.busyJob=mode; S.jobLabel=label; Object.assign(S.p,{status:'PROCESSING',stage:mode==='render'||mode==='transcribe'?'QUEUING':mode==='dub'?'TTS':'TRANSLATE',progress:0}); if(isOcr){ S.p.subtitleSource='ocr'; S.segs=[]; S.sel=null; S.ocrLogs=[]; pushOcrLog(t('OCR V2 khởi động — fast scan → adaptive sampling → tracking → refinement.','OCR V2 started — fast scan → adaptive sampling → tracking → refinement.'),0); connectOcrEvents(); } else startPolling(); renderTop(); renderSegs(); renderStageInfo(); renderOcrLiveLog(); if(mode==='render'||(mode==='transcribe'&&!isOcr)) showProcessing(); }catch(e){ toast(e.message||t('Không thể bắt đầu tác vụ','Could not start the job'),'error'); } }
async function cancelJob(){ try{ await api.cancel(S.p.id); S.p.status='CANCELLED'; S.p.stage=null; S.busyJob=null; toast(t('Đã hủy tác vụ','Job cancelled'),'warning'); closeProcessing(); renderAll(); }catch(e){ toast(e.message,'error'); } }
let pollTimer=null, polling=false;
function startPolling(){ if(!pollTimer) pollTimer=setInterval(poll,CFG.pollMs); }
async function poll(){ if(polling||!S.p) return; if(S.busyJob==='transcribe' && S.p.subtitleSource==='ocr' && ocrSseConnected) return; polling=true; try{ const p=await api.getProject(S.p.id); const wasBusy=busy(); Object.assign(S.p,{status:p.status,stage:p.stage,progress:p.progress,queuePosition:p.queuePosition,latestOutputId:p.latestOutputId,error:p.error,translationMissingSegments:Array.isArray(p.translation_missing_segments)?p.translation_missing_segments:(S.p.translationMissingSegments||[])}); const segs=await api.getSegments(S.p.id); const map=new Map(segs.map(s=>[s.id,s])); S.segs=S.segs.map(s=>{ const n=map.get(s.id); if(!n) return s; return Object.assign({},n,{txStatus:s.txStatus==='running'?'running':n.txStatus,dubStatus:s.dubStatus==='running'?'running':n.dubStatus}); }); segs.forEach(n=>{ if(!segById(n.id)) S.segs.push(n); }); if(S.busyJob==='transcribe'&&!busy()) S.segs=segs; renderSegList(); drawTimeline(); renderProcessing(); renderStageInfo(); if(wasBusy&&!busy()){ clearInterval(pollTimer); pollTimer=null; const mode=S.busyJob; S.busyJob=null; await onJobDone(mode); renderAll(); } else { renderTop(); renderSegHead(); } }catch(e){} finally{ polling=false; } }
async function onJobDone(mode){ const p=S.p; if(p.status==='FAILED'){ toast(p.error||t('Xử lý thất bại','Processing failed'),'error'); closeProcessing(); return; } if(p.status==='CANCELLED'){ closeProcessing(); return; } if(mode==='translate') toast(t('Đã dịch xong toàn bộ phân đoạn','All segments translated'),'success'); if(mode==='dub') toast(t('Đã lồng tiếng xong','Dubbing complete'),'success'); if(mode==='transcribe'){ toast(t('Đã phân tích lại phụ đề','Transcript re-run complete'),'success'); closeProcessing(); } if(mode==='render'){ toast(t('Kết xuất video thành công','Video rendered successfully'),'success'); closeProcessing(); showResults(); } }

